package net.officefloor.hq.app.rate;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A rate for a grade on a sheet: a percent with two decimals, in force from its from-date (or from the
 * beginning of time when it has none) until the grade's next later-dated rate, and only through its to-date
 * when it has one.
 */
@Entity
@Table(name = "rate")
public class Rate {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "grade", nullable = false)
    private String grade;

    @Column(name = "pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal pct;

    /** The first day the rate applies; null when it applies from the beginning of time. */
    @Column(name = "from_date")
    private LocalDate fromDate;

    /** The last day the rate applies; null when it applies until the grade's next later-dated rate. */
    @Column(name = "to_date")
    private LocalDate toDate;

    protected Rate() {
    }

    public Rate(String sheetId, String grade, LocalDate fromDate, BigDecimal pct) {
        this.sheetId = sheetId;
        this.grade = grade;
        this.fromDate = fromDate;
        this.pct = pct;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getGrade() {
        return grade;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    public void setToDate(LocalDate toDate) {
        this.toDate = toDate;
    }

    /** Whether the rate applies on the date, given it is the grade's latest-dated rate on or before it. */
    public boolean appliesOn(LocalDate date) {
        return toDate == null || !date.isAfter(toDate);
    }

    public BigDecimal getPct() {
        return pct;
    }

    public void setPct(BigDecimal pct) {
        this.pct = pct;
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Keeps the rates for each grade on a sheet, each in force from its from-date. */
@Service
public class RateService {

    private final RateRepository rates;
    private final RateLogRepository logs;
    private final SheetRepository sheets;
    private final Audit audit;
    private final RollupService rollup;

    public RateService(RateRepository rates, RateLogRepository logs, SheetRepository sheets, Audit audit,
            RollupService rollup) {
        this.rates = rates;
        this.logs = logs;
        this.sheets = sheets;
        this.audit = audit;
        this.rollup = rollup;
    }

    /**
     * The sheet's rates, then each parent sheet's up to {@link RollupService#PARENT_LEVELS} levels up (nearest first),
     * each in grade order then by from-date.
     */
    public List<List<Rate>> chain(String sheetId) {
        return rollup.rateChain(sheetId);
    }

    /**
     * The grade's rate in force on the date: the one with the latest from-date on or before it, an
     * undated rate counting as from the beginning of time. Empty when the date is before every rate, or
     * after that rate's to-date. With none on the sheet, the parent sheet's, then its parent's, up to three levels up.
     */
    public Optional<Rate> rateOn(String sheetId, String grade, LocalDate date) {
        return RollupService.rateOn(rollup.rateChain(sheetId), grade, date);
    }

    /**
     * The grade's rate percent in force on the date as the rates stood at the end of {@code asOf}: each from-date's
     * last setting made while the sheet's today was on or before it (a rate set before settings were logged counts as
     * it is now). With none on the sheet then, the parent sheets' rates in force on the date as they stood then.
     * Empty when the grade had no rate in force on the date then.
     */
    public Optional<BigDecimal> rateAsOf(String sheetId, String grade, LocalDate date, LocalDate asOf) {
        List<Rate> stood = RateLog.stood(sheetId, grade, rates.findBySheetIdAndGrade(sheetId, grade),
                logs.findBySheetIdAndGradeOrderByIdAsc(sheetId, grade), asOf);
        Optional<BigDecimal> own = stood.stream()
                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .filter(r -> r.appliesOn(date))
                .map(Rate::getPct);
        if (own.isPresent()) {
            return own;
        }
        List<List<Rate>> chain = rollup.rateChain(sheetId, asOf);
        return RollupService.rateOn(chain.subList(1, chain.size()), grade, date).map(Rate::getPct);
    }

    /** What the grade having the percent on every date would change on the sheet; nothing is saved. */
    @Transactional(readOnly = true)
    public RollupService.RatePreview preview(String sheetId, String grade, BigDecimal pct) {
        if (!sheets.existsById(sheetId)) {
            throw new SheetNotFoundException(sheetId);
        }
        return rollup.preview(sheetId, grade, pct);
    }

    /**
     * Set the grade's rate from the from-date (null: from the beginning of time) through the to-date (null: no
     * end), replacing the one it had; a to-date before the from-date is refused.
     */
    @Transactional
    public Rate set(String sheetId, String user, String grade, LocalDate fromDate, LocalDate toDate, BigDecimal pct) {
        if (!sheets.existsById(sheetId)) {
            throw new SheetNotFoundException(sheetId);
        }
        if (fromDate != null && toDate != null && toDate.isBefore(fromDate)) {
            throw new RateDatesException(fromDate, toDate);
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Rate rate = rates.findBySheetIdAndGradeAndFromDate(sheetId, grade, fromDate).orElse(null);
        if (rate == null) {
            rate = new Rate(sheetId, grade, fromDate, pct);
        } else {
            rate.setPct(pct);
        }
        rate.setToDate(toDate);
        Rate saved;
        try {
            saved = rates.saveAndFlush(rate);
        } catch (DataIntegrityViolationException e) {
            throw new RateTakenException(sheetId, grade);
        }
        logs.save(new RateLog(saved, sheets.findById(sheetId).orElseThrow().getToday()));
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user + " grade=" + saved.getGrade()
                + " rate=" + saved.getPct().setScale(2, RoundingMode.UNNECESSARY).toPlainString()
                + (saved.getFromDate() == null ? "" : " from=" + saved.getFromDate())
                + (saved.getToDate() == null ? "" : " to=" + saved.getToDate()));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }
}
package net.officefloor.hq.app.rate;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

/** One setting of a grade's rate: its from- and to-dates and percent as set, and the sheet's today when it was set. */
@Entity
@Table(name = "rate_log")
public class RateLog {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "grade", nullable = false)
    private String grade;

    @Column(name = "from_date")
    private LocalDate fromDate;

    @Column(name = "to_date")
    private LocalDate toDate;

    @Column(name = "pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal pct;

    @Column(name = "set_on", nullable = false)
    private LocalDate setOn;

    protected RateLog() {
    }

    RateLog(Rate rate, LocalDate setOn) {
        this.sheetId = rate.getSheetId();
        this.grade = rate.getGrade();
        this.fromDate = rate.getFromDate();
        this.toDate = rate.getToDate();
        this.pct = rate.getPct();
        this.setOn = setOn;
    }

    /** A copy of the log line on another sheet. */
    public RateLog copyTo(String sheetId) {
        RateLog copy = new RateLog();
        copy.sheetId = sheetId;
        copy.grade = grade;
        copy.fromDate = fromDate;
        copy.toDate = toDate;
        copy.pct = pct;
        copy.setOn = setOn;
        return copy;
    }

    public Long getId() {
        return id;
    }

    public String getGrade() {
        return grade;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    public BigDecimal getPct() {
        return pct;
    }

    public LocalDate getSetOn() {
        return setOn;
    }

    /**
     * A grade's rates on a sheet as they stood at the end of {@code asOf}: each from-date's last setting made while the
     * sheet's today was on or before it (a rate set before settings were logged counts as it is now).
     *
     * @param now the grade's rates as they are now
     * @param set the grade's rate settings, in the order they were made
     */
    public static List<Rate> stood(String sheetId, String grade, List<Rate> now, List<RateLog> set, LocalDate asOf) {
        Map<LocalDate, RateLog> then = new LinkedHashMap<>();
        for (RateLog log : set) {
            if (!log.getSetOn().isAfter(asOf)) {
                then.put(log.getFromDate(), log);
            }
        }
        List<Rate> stood = new ArrayList<>();
        for (Rate rate : now) {
            boolean logged = set.stream().anyMatch(l -> Objects.equals(l.getFromDate(), rate.getFromDate()));
            if (!logged) {
                stood.add(rate);
            }
        }
        for (RateLog log : then.values()) {
            Rate rate = new Rate(sheetId, grade, log.getFromDate(), log.getPct());
            rate.setToDate(log.getToDate());
            stood.add(rate);
        }
        return stood;
    }
}
